
local eyed=[==[]==]
local evs=
(function(...)
local ksmx={187,156,124,244,102,165,160,18,241,211,254,84,171,76,228,232,99}
local zci=bit32 or bit
local gtwj=zci.bxor
for ld=1,#ksmx do ksmx[ld]=gtwj(ksmx[ld],(109*ld+62)%256) end
local hgu="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local rbq={}
for jkuf=1,#hgu do rbq[hgu:byte(jkuf)]=jkuf-1 end
local function lbl(str)
  local R={} local acc,nb=0,0
  for my=1,#str do
    local v=rbq[str:byte(my)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function aogp(key,data)
  local S={} for gzduo=0,255 do S[gzduo]=gzduo end
  local j=0
  for rqz=0,255 do
    j=(j+S[rqz]+key[(rqz%#key)+1])%256
    S[rqz],S[j]=S[j],S[rqz]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(gtwj(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=aogp(ksmx,lbl(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local tsytd=nf()
return function(big) return tsytd(big) end
end)(...)

return evs(eyed)
